const result = await fetch('/api/com.ictrek.v-scheduler/v1/chat/completions', {
  method: 'POST',
  headers: {Authorization: 'Bearer ' + token, 'Content-Type': 'application/json'},
  body: JSON.stringify({model: 'v-scheduler/ollama-qa/<model>', messages: [{role: 'user', content: 'Hello'}]})
});

const token = await vosFastpathToken();
const models = await fetch('/api/com.ictrek.v-scheduler/v1/models', {
  headers: { Authorization: 'Bearer ' + token }
}).then(r => r.json());
// 用 models.data[].id 填充模型下拉框；不要在本应用保存云端 key、上游地址或模型清单。

const detail = await fetch('/api/com.ictrek.v-scheduler/api/v1/models', {
  headers: { Authorization: 'Bearer ' + token }
}).then(r => r.json());
// detail.models 包含 qualified、kind、capabilities、endpoints、upstream_kind、model_prefix，可用于筛选对话/Embedding 下拉。
